int numberOfWays(int n, int k) {
    // Create a DP table with dimensions (n + 1) x (k + 1), initialized to -1
    vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, -1));

    // Lambda for memoized recursive computation
    auto solve = [&](auto& self, int curr_n, int curr_k) -> long long {
        if (curr_n == 0) return 1;
        if (curr_k == 0) return 1;
        if (dp[curr_n][curr_k] != -1) return dp[curr_n][curr_k];

