    for (int j = 1; j <= n; ++j) {
        for (int i = 1; i <= m; ++i) {
            if (i < j) {
                dp[i][j] = 0;
            } else {
                // dp[i][j] = (sequences not using i) + (sequences using i at least once)
                // Which translates to dp[i-1][j] + dp[i/2][j-1]
                dp[i][j] = dp[i - 1][j] + dp[i / 2][j - 1];
            }
        }
    }

    return dp[m][n];
}

